def compute(vars):
    shares = vars["v1"]
    holders = vars["v2"]

    if holders == 0:
        return None

    average_shares_per_holder = shares / holders

    return {
        "value": average_shares_per_holder,
        "trace": {
            "outstanding_shares": shares,
            "registered_holders": holders,
            "average_shares_per_holder": average_shares_per_holder,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares per registered holder"
            }
        }
    }
